import { useState, useEffect, useRef } from 'react'
import { usePublicClient } from 'wagmi'
import { useGuestChain } from './useGuestChain.js'
import { useTxHistory } from './useTxHistory.js'
import { useTxStatusWatcher } from './useTxStatusWatcher.js'
import { getTxUrl, fmtDisplay } from './chainUtils.js'

const PAGE_SIZE = 8


function shortHash(h) {
  if (!h || h.length < 14) return h
  return h.slice(0, 8) + '…' + h.slice(-6)
}

const TYPE_META = {
  'Private Deposit': { icon: '↓', color: '#00b4d8', bg: 'rgba(0,180,216,0.08)',  border: 'rgba(0,180,216,0.18)' },
  'Private Withdraw': { icon: '↑', color: '#00d395', bg: 'rgba(0,211,149,0.08)',  border: 'rgba(0,211,149,0.18)' },
  Deposit:        { icon: '↓', color: '#00b4d8', bg: 'rgba(0,180,216,0.08)',  border: 'rgba(0,180,216,0.18)' },
  Withdraw:       { icon: '↑', color: '#00d395', bg: 'rgba(0,211,149,0.08)',  border: 'rgba(0,211,149,0.18)' },
  Approve:        { icon: '✓', color: '#a78bfa', bg: 'rgba(167,139,250,0.08)', border: 'rgba(167,139,250,0.18)' },
  'Safe Deposit':  { icon: '↓', color: '#00b4d8', bg: 'rgba(0,180,216,0.08)',  border: 'rgba(0,180,216,0.18)' },
  'Safe Withdraw': { icon: '↑', color: '#00d395', bg: 'rgba(0,211,149,0.08)',  border: 'rgba(0,211,149,0.18)' },
}

function getTypeMeta(type) {
  return TYPE_META[type] || { icon: '·', color: 'rgba(255,255,255,0.4)', bg: 'rgba(255,255,255,0.04)', border: 'rgba(255,255,255,0.08)' }
}

function StatusBadge({ status }) {
  if (status === 'success') return <span className="txh-badge txh-badge-ok">✓ Success</span>
  if (status === 'failed')  return <span className="txh-badge txh-badge-fail">✕ Failed</span>
  return <span className="txh-badge txh-badge-pending"><span className="txh-spin">⟳</span> Pending</span>
}

export default function TxHistory() {
  const { txs, deleteTx, clearTxs } = useTxHistory()
  const { activeChainId: chainId } = useGuestChain()
  const [page, setPage] = useState(0)
  const [confirmClear, setConfirmClear] = useState(false)
  useTxStatusWatcher()

  const all = txs.filter(t => t.chainId === chainId)
  const totalPages = Math.ceil(all.length / PAGE_SIZE)
  const visible = all.slice(page * PAGE_SIZE, page * PAGE_SIZE + PAGE_SIZE)

  if (!all.length) return null

  return (
    <div className="txh-wrap">
      <div className="txh-header">
        <span className="txh-title">Hash History</span>
        <div style={{ display:'flex', gap:'6px', alignItems:'center' }}>
          <span className="txh-count">{all.length} records</span>
          {confirmClear
            ? <>
                <span style={{fontSize:'11px',color:'var(--warn)'}}>Sure?</span>
                <button className="btn-danger" style={{padding:'3px 10px',fontSize:'11px'}} onClick={() => { clearTxs(); setConfirmClear(false) }}>Yes</button>
                <button className="tkt-btn" style={{padding:'3px 10px',fontSize:'11px'}} onClick={() => setConfirmClear(false)}>No</button>
              </>
            : <button className="btn-danger" style={{padding:'3px 10px',fontSize:'11px'}} onClick={() => setConfirmClear(true)}>Clear</button>
          }
        </div>
      </div>

      <div className="txh-list">
        {visible.map(tx => {
          const url = getTxUrl(tx.chainId, tx.hash)
          const tm = getTypeMeta(tx.type)
          return (
            <div key={tx.hash} className="txh-row">
              {/* Type icon */}
              <div className="txh-type-icon" style={{ background: tm.bg, border: `1px solid ${tm.border}`, color: tm.color }}>
                {tm.icon}
              </div>

              {/* Main info */}
              <div className="txh-info">
                <div className="txh-info-top">
                  <span className="txh-type-label" style={{ color: tm.color }}>{tx.type}</span>
                  <span className="txh-amount">{(() => { const s = String(tx.amount); const d = s.indexOf('.'); return d === -1 ? s : s.slice(0, d + 7).replace(/\.?0+$/, '') })()} {tx.currency}</span>
                </div>
                <div className="txh-info-bot">
                  <span className="txh-hash">{shortHash(tx.hash)}</span>
                  <span className="txh-time">{new Date(tx.ts).toLocaleString()}</span>
                </div>
              </div>

              {/* Right: status + link + delete */}
              <div className="txh-right">
                <StatusBadge status={tx.status} />
                <div style={{ display:'flex', gap:'4px', marginTop:'4px' }}>
                  {url && (
                    <a href={url} target="_blank" rel="noreferrer" className="txh-link" title="View on explorer">↗</a>
                  )}
                  <button className="txh-del" onClick={() => deleteTx(tx.hash)} title="Remove">✕</button>
                </div>
              </div>
            </div>
          )
        })}
      </div>

      {totalPages > 1 && (
        <div className="txh-pagination">
          <button className="btn-copy" style={{ padding:'4px 12px' }} disabled={page === 0} onClick={() => setPage(p => p - 1)}>‹</button>
          <span className="txh-page-info">{page + 1} / {totalPages}</span>
          <button className="btn-copy" style={{ padding:'4px 12px' }} disabled={page >= totalPages - 1} onClick={() => setPage(p => p + 1)}>›</button>
        </div>
      )}
    </div>
  )
}
